 30 │ <!-- [PHYSICS-CORE-START] ... [PHYSICS-CORE-END]                        -->
 31 │ <!-- =================================================================== -->
 32 │ <script id="physics-core">
 33 │ /* @physics-core-start */
 34 │ /* d20 = regular icosahedron. 12 vertices (golden-ratio construction),
 35 │    20 equilateral faces numbered 1..20, opposite faces sum to 21.
 36 │    6-DOF rigid body: pos(3), quat(4), linVel(3), angVel(3).
 37 │    Semi-implicit Euler, fixed sub-steps. Table = plane y=0.
 38 │    Contact = lowest vertex (or two near-tied vertices); impulse with
 39 │    restitution (normal) + Coulomb friction (tangential) + angular loss.
 40 │    Soft rectangular walls. Settle detector + face-up read.
 41 │    Deterministic: NO Math.random() in this path. */
 42 │ (function (global) {
 43 │   'use strict';
 44 │ 
 45 │   // ---- constants (SI-ish; feel tuned later, correctness first) ---------
 46 │   const G = 9.817;               // gravity (m/s^2)
 47 │   const R_CIRC = 0.03;           // die circumscribed radius (m), vertex->center
 48 │   const MASS = 0.01;             // die mass (10 g)
 49 │   const SUB_DT = 1 / 240;        // fixed physics sub-step (s)
 50 │   const RESTITUTION = 0.35;      // table normal restitution
 51 │   const FRICTION = 0.5;          // table Coulomb mu
 52 │   const WALL_E = 0.4;            // wall restitution
 53 │   const WALL_F = 0.6;            // wall friction
 54 │   const CONTACT_ANG_LOSS = 0.02; // angular energy bleed per sub-step on contact
 55 │   const REST_LIN = 0.03;         // m/s: |v| below this counts as "still"
 56 │   const REST_ANG = 1.0;          // rad/s: |w| below this counts as "still"
 57 │   const REST_WINDOW = 0.15;      // s of sustained stillness to declare rest
 58 │   const SETTLE_T_MAX = 25;       // s: hard cap to declare "settled" (defensive)
 59 │   const TABLE_HALF = 0.24;       // soft-wall half-extent (m) -> 0.48 x 0.48 table
 60 │   const TWO_V_TOL = R_CIRC * 0.06; // near-tied lowest-vertex tolerance (m)
 61 │   const V_REST = 0.25;           // m/s: below this approach speed, restitution e=0
 62 │   const PEN_CORRECT = 0.12;      // fraction of penetration removed per sub-step
 63 │   const PEN_EPS = 1e-6;          // m: ignore penetration smaller than this
 64 │   // Rest damper: bleeds the low-energy rock to a full stop. Real dice lose
 65 │   // energy at the contact point (friction, deformation); the rocking on a
 66 │   // face is damped by friction at the pivot. This is that contact energy loss,
 67 │   // applied only while the die is already slow and in contact with the table,
 68 │   // so it never touches the throw or the bounces.
 69 │   const SLOW_VEL = 0.4;          // m/s: speed below which the rest damper engages
 70 │   const SLOW_ANG = 3.5;          // rad/s: speed below which the rest damper engages
 71 │   const REST_DAMP = 0.35;        // per-substep exponential decay of speed at rest
 72 │ 
 73 │   // ---- deterministic PRNG (mulberry32); ONLY for generating test states --
 74 │   function prng(seed) {
 75 │     let a = seed >>> 0;
 76 │     return function () {
 77 │       a = (a + 0x6D2B79F5) >>> 0;
 78 │       let t = a;
 79 │       t = Math.imul(t ^ (t >>> 15), t | 1);
 80 │       t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
 81 │       return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
 82 │     };
 83 │   }
 84 │ 
 85 │   // ---- vector helpers (plain [x,y,z]) ----------------------------------
 86 │   const v3 = (x, y, z) => [x, y, z];
 87 │   const vAdd = (a, b) => [a[0]+b[0], a[1]+b[1], a[2]+b[2]];
 88 │   const vSub = (a, b) => [a[0]-b[0], a[1]-b[1], a[2]-b[2]];
 89 │   const vScale = (a, s) => [a[0]*s, a[1]*s, a[2]*s];
 90 │   const vDot = (a, b) => a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
 91 │   const vCross = (a, b) => [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
 92 │   const vLen = a => Math.sqrt(vDot(a, a));
 93 │   const vNorm = a => { const l = vLen(a); return l > 1e-12 ? vScale(a, 1/l) : v3(0,0,0); };
 94 │ 
 95 │   // ---- quaternion helpers (x,y,z,w) ------------------------------------
 96 │   const qIdentity = () => [0, 0, 0, 1];
 97 │   function qFromAxisAngle(axis, angle) {
 98 │     const s = Math.sin(angle / 2), c = Math.cos(angle / 2);
 99 │     const a = vNorm(axis);
100 │     return [a[0]*s, a[1]*s, a[2]*s, c];
101 │   }
102 │   function qMul(a, b) {
103 │     const ax=a[0], ay=a[1], az=a[2], aw=a[3];
104 │     const bx=b[0], by=b[1], bz=b[2], bw=b[3];
105 │     return [
106 │       aw*bx + ax*bw + ay*bz - az*by,
107 │       aw*by - ax*bz + ay*bw + az*bx,
108 │       aw*bz + ax*by - ay*bx + az*bw,
109 │       aw*bw - ax*bx - ay*by - az*bz
110 │     ];
111 │   }
112 │   function qNorm(q) {
113 │     const l = Math.sqrt(q[0]*q[0]+q[1]*q[1]+q[2]*q[2]+q[3]*q[3]);
114 │     return l > 1e-12 ? [q[0]/l, q[1]/l, q[2]/l, q[3]/l] : qIdentity();
115 │   }
116 │   function qRotate(q, v) { // v' = q v q^-1 (q unit)
117 │     const x=q[0], y=q[1], z=q[2], w=q[3];
118 │     const tx = 2*(y*v[2] - z*v[1]);
119 │     const ty = 2*(z*v[0] - x*v[2]);
120 │     const tz = 2*(x*v[1] - y*v[0]);
121 │     return [
122 │       v[0] + w*tx + (y*tz - z*ty),
123 │       v[1] + w*ty + (z*tx - x*tz),
124 │       v[2] + w*tz + (x*ty - y*tx)
125 │     ];
126 │   }
127 │ 
128 │   // ---- convex-polyhedron face extraction --------------------------------
129 │   // Returns { faces: index-triples, edges, adj } for a convex polyhedron.
130 │   function extractFaces(vertices) {
131 │     const n = vertices.length;
132 │     let edge = Infinity;
133 │     for (let i = 0; i < n; i++) for (let j = i+1; j < n; j++) {
134 │       const d = vLen(vSub(vertices[i], vertices[j]));
135 │       if (d < edge) edge = d;
136 │     }
137 │     const adj = Array.from({length: n}, () => []);
138 │     const EPS = edge * 1e-6;
139 │     for (let i = 0; i < n; i++) for (let j = i+1; j < n; j++) {
140 │       if (Math.abs(vLen(vSub(vertices[i], vertices[j])) - edge) < EPS) { adj[i].push(j); adj[j].push(i); }
141 │     }
142 │     // face test: (i,j,k) is a face iff i-j and j-k are edges and the three are
143 │     // coplanar & form an outward triangle. For a convex polyhedron, each edge
144 │     // bounds exactly two faces. We enumerate, per vertex, the 5 neighbors in
145 │     // angular order about the radial direction; consecutive pairs are faces.
146 │     const faceSet = new Set();
147 │     const key = (a,b,c) => [a,b,c].sort((x,y)=>x-y).join(',');
148 │     for (let i = 0; i < n; i++) {
149 │       const ri = vNorm(vertices[i]);
150 │       let ref = [1,0,0];
151 │       if (Math.abs(vDot(ri, ref)) > 0.9) ref = [0,1,0];
152 │       const u = vNorm(vSub(ref, vScale(ri, vDot(ri, ref)))); // ref minus radial comp
153 │       const w = vNorm(vCross(ri, u));
154 │       const order = adj[i].map(nn => {
155 │         const d = vNorm(vSub(vertices[nn], vertices[i]));
156 │         return [nn, Math.atan2(vDot(d, w), vDot(d, u))];
157 │       }).sort((p, q) => p[1] - q[1]);
158 │       for (let k = 0; k < order.length; k++) {
159 │         const a = order[k][0], b = order[(k + 1) % order.length][0];
160 │         faceSet.add(key(i, a, b));
161 │       }
162 │     }
163 │     const faces = Array.from(faceSet).map(s => s.split(',').map(Number));
164 │     // consistent winding: outward normal (a x b) dot (centroid) > 0
165 │     for (let f = 0; f < faces.length; f++) {
166 │       const [a, b, c] = faces[f];
167 │       const A = vertices[a], B = vertices[b], C = vertices[c];
168 │       const nm = vCross(vSub(B, A), vSub(C, A));
169 │       const cent = vScale(vAdd(vAdd(A, B), C), 1/3);
170 │       if (vDot(nm, cent) < 0) faces[f] = [c, b, a]; // flip to outward
171 │     }
172 │     return { faces, adj };
173 │   }
174 │ 
175 │   // ---- exact inertia tensor of a uniform solid polyhedron (Robbins 1976) -
176 │   // Polyhedron = union of tetrahedra (origin, face-triangle). Each contributes
177 │   // V/30 * (sum of products of vertex coords) to the inertia components.
178 │   function solidInertia(vertices, faces, mass) {
179 │     // outward-wound face triangles as world vertex coords
